package com.stackgen.metadataservice.entity;
import jakarta.persistence.*; import java.util.UUID;
@Entity @Table(name="entity_fields", indexes=@Index(name="idx_entity_fields_entity", columnList="entity_id"))
public class EntityField { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="entity_id",nullable=false) private UUID entityId; @Column(nullable=false,length=100) private String name; @Column(name="data_type",nullable=false,length=50) private String dataType; @Column(name="is_nullable",nullable=false) private boolean nullable=true; @Column(name="is_unique",nullable=false) private boolean unique; @Column(name="is_primary_key",nullable=false) private boolean primaryKey; @Column(name="default_value",length=255) private String defaultValue; @Column(columnDefinition="text") private String validations; @Column(name="display_order",nullable=false) private int displayOrder;
 public UUID getId(){return id;} public UUID getEntityId(){return entityId;} public void setEntityId(UUID v){entityId=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getDataType(){return dataType;} public void setDataType(String v){dataType=v;} public boolean isNullable(){return nullable;} public void setNullable(boolean v){nullable=v;} public boolean isUnique(){return unique;} public void setUnique(boolean v){unique=v;} public boolean isPrimaryKey(){return primaryKey;} public void setPrimaryKey(boolean v){primaryKey=v;} public String getDefaultValue(){return defaultValue;} public void setDefaultValue(String v){defaultValue=v;} public String getValidations(){return validations;} public void setValidations(String v){validations=v;} public int getDisplayOrder(){return displayOrder;} public void setDisplayOrder(int v){displayOrder=v;}
}
